-- Modify "servers" table
ALTER TABLE "public"."servers" ADD CONSTRAINT "servers_color_check" CHECK ((color IS NULL) OR (color ~ '^#[0-9A-Fa-f]{6}$'::text)), ADD CONSTRAINT "servers_icon_check" CHECK ((icon IS NULL) OR (icon = ANY (ARRAY['server'::text, 'database'::text, 'globe'::text, 'cloud'::text, 'cpu'::text, 'box'::text, 'rocket'::text, 'shield'::text, 'code'::text, 'terminal'::text, 'layers'::text, 'zap'::text, 'flame'::text, 'leaf'::text, 'star'::text, 'heart'::text, 'briefcase'::text, 'home'::text, 'store'::text, 'graduation-cap'::text, 'building'::text, 'gamepad'::text, 'music'::text, 'camera'::text]))), ADD CONSTRAINT "servers_logo_url_check" CHECK ((logo_url IS NULL) OR ((logo_url ~~ 'https://%'::text) AND (length(logo_url) <= 500))), ADD COLUMN "color" text NULL, ADD COLUMN "icon" text NULL, ADD COLUMN "logo_url" text NULL;
